INSERT INTO film (title, runtime_minutes, tmdb_id, overview, poster_path, released_on)
VALUES
    ('Hope', 157, 1058424, 'In the remote South Korean village of Hope Harbor, police chief Bum-seok and officer Sung-ae are called to investigate a mysterious creature wreaking havoc on the community. But all is not as it seems, and perceptions can be misleading. What begins as ignorance plants the seed of disaster, escalating through human conflict into a tragedy of cosmic proportions.', '/6VY1ZKgpsc8CfGsQcCGiYEgHdH0.jpg', '2026-07-15'),
    ('The Hunger Games: Sunrise on the Reaping', 159, 1300968, 'Return to the world of Panem 24 years before the events of The Hunger Games, starting on the morning of the reaping of the 50th Hunger Games, also known as the Second Quarter Quell.', '/nzIXSQNgYZwFOMrmv0d0I3ulvkM.jpg', '2026-11-18'),
    ('Ramayana: Rise of a Legend', 195, 656908, 'An ancient epic follows a young prince and princess whose marriage and subsequent exile mark the beginning of a legendary journey. Their story of love, duty and destiny sets the stage for greater challenges ahead.', '/vBQ7wks68OhJKlb3RnXSl2yXBXK.jpg', '2026-11-05'),
    ('Ebenezer', 115, 1567605, 'An elderly miser embarks on a supernatural journey after visits from the ghost of his former business partner and the Spirits of Christmas Past, Present, and Yet to Come force him to confront his past and fight for a second chance at happiness.', '/6H2N59jJW1hZEzn2ZdrMvJw5vNI.jpg', '2026-11-11'),
    ('Godzilla Minus Zero', 135, 1381071, 'War reduced Japan to zero, and Godzilla plunged it into minus. Two years have passed since then, and the country has faced agonizing struggles to achieve recovery and finally reclaim its daily life. Just as humanity managed to cling to a hard-won peace, a new threat strikes, crushing hope in an instant. There is no third time. Everything ends here.', '/hSmIJluOJmTWvJs4d7kHRxjc8s8.jpg', '2026-11-03'),
    ('Ghost Soldier', 90, 1562642, 'Henry “Fitz” Fitzgerald has spent years living quietly off the grid, hiding from a past few people know anything about. But when a powerful foreign corporation moves into his hometown to seize his neighbors’ land for a massive payday, Fitz is forced to reveal who he really is: a former Special Forces soldier and advanced weapons developer. Armed with experimental technology, lethal combat skills, and an unwavering code of justice, Fitz wages a one-man war against an enemy that never saw him coming.', '/8Y4oJ5iUs3hgPcDB3SIEmsNYjZk.jpg', '2026-11-06'),
    ('LA BOLA NEGRA', 159, 1422041, 'The intertwined lives of three men in three different eras, three lives intimately linked by sexuality and desire, pain, and legacy.', '/7HwFQTMghL6HOvzEnXYUvyuZXeh.jpg', '2026-09-25'),
    ('Street Fighter', 120, 1153576, 'In 1993, estranged Street Fighters Ryu and Ken Masters are thrown back into combat when the mysterious Chun-Li recruits them for the next World Warrior Tournament: a brutal clash of fists, fate, and fury. But behind this battle royale lies a deadly conspiracy that forces them to face off against each other and the demons of their past. And if they don''t, it''s GAME OVER!', '/ccxdepKqORLwccbzvO4eAGkN0IC.jpg', '2026-10-13'),
    ('Wildwood', 132, 791523, 'Prue and her classmate Curtis are drawn into a magical forest filled with enchanted creatures, loyal allies, and formidable adversaries as they embark on a desperate quest to rescue Prue''s abducted baby brother from a murder of crows led by a mysterious woman named Alexandra.', '/snFM00mpNAfUzUtkdEW0uDEvXA0.jpg', '2026-10-19'),
    ('How to Rob a Bank', 122, 1437511, 'A crew of social media-savvy bank robbers broadcasts their daring heists, unaware that their growing viral fame has put them in the crosshairs of a veteran FBI agent and a brilliant software engineer. Despite the unlikely duo closing in, the crime ring pushes past their limits, putting everything on the line for their most ambitious heist yet.', '/ifYDZkr2qkHFz87TNVvlxajOxl5.jpg', '2026-11-10'),
    ('Clayface', 109, 1400940, 'Matt Hagen''s meteoric rise from Gotham street kid to Hollywood leading man is tragically cut short when a local crime boss''s actions leave him horribly disfigured. Abandoned by his team and with nothing left, Matt seeks out a cutting edge treatment that miraculously returns him to his former self… but also unexpectedly affects his grip on reality, spiraling him down a destructive path of all-consuming revenge.', '/9l1NuFjel2j89hiuiJbsxfblqjy.jpg', '2026-10-19'),
    ('You Can See Everything', 175, 1765072, 'Thirty-four days before she''s sent to prison, notorious Silicon Valley founder Elizabeth Holmes invites a skeptical film crew to document her every move. What begins as an intimate portrait of an enigmatic felon becomes a mind-bending three-year journey into the abyss.', '/mVh3qkw2NUFxWWyF0G1hg2Wh0K5.jpg', '2026-10-16'),
    ('Wild Horse Nine', 117, 891621, 'Shortly before the 1973 Chilean coup, CIA agents Chris and Lee are dispatched from Santiago to Easter Island by their bureau chief, MJ. Amongst the Island''s iconic statues, and as the longtime partners wrestle with their dark pasts and present conspiracies, Chris''s newfound bond with a pair of rebellious students threatens to send everyone’s trip to this remote paradise sideways.', '/dNJFRtVg3xLQ7dbNIQ55cmmIniD.jpg', '2026-10-30'),
    ('The Cat in the Hat', 108, 1117898, 'Assigned his toughest mission yet, the Cat must cheer up siblings Gabby and Sebastian as they adjust to life in a new town. Known for pushing boundaries, this agent of chaos must prove himself or risk losing his magical hat forever.', '/mWN6knIVJ2o7eGwSm7mOgSCwNUc.jpg', '2026-10-31'),
    ('A Talent for Murder', 106, 1084409, 'A young man travels from New York to Switzerland to try to persuade acclaimed thriller writer Patricia Highsmith to write one final installment of her Tom Ripley series, with his efforts gradually turning more sinister.', '/mstDPKNKgSGFvVFVdfzeMNkcyw2.jpg', '2026-10-23'),
    ('Forgotten Island', 109, 1465063, 'While celebrating their last night together, high school graduates and best friends Jo and Raissa stumble upon a mysterious portal that transports them to the fantastical island of Nakali. When they discover that the memories of their entire friendship are the price for returning home, Jo and Raissa must race to find a way to leave the island before they forget each other forever.', '/myd1K3gefdNAWFsGNRDdMeiK9Qg.jpg', '2026-09-10'),
    ('Jailer 2', 165, 1234139, 'When a dangerous syndicate threatens his family, retired jailer Tiger Muthuvel Pandian goes undercover as a driver to battle enemies from the shadows.', '/upwdEyhhYZ7pT2hD535fr2MGfpx.jpg', '2026-10-14'),
    ('Wicker', 105, 1195803, 'On the outskirts of a village by the sea, lives a Fisherwoman; smelly, single and perpetually ridiculed. One day, fed up with her stuffy, small-minded neighbours, she commissions herself a husband to be made from wicker. In an otherwise conservative town, this unconventional romance sparks outrage, jealousy and chaos.', '/6FcBZOKvyrLCKGCyBG0ySCR4okt.jpg', '2026-10-21'),
    ('Your Mother Your Mother Your Mother', 112, 1437396, 'Latif, a devoutly religious hitman, struggles to balance work, faith and fatherhood. When his wife dies, he embarks on a desperate journey across Houston to protect his children, confronting the forces closing in around him – and the beliefs threatening to unravel within.', '/4KaPZSKnInnArErTTgy9Oy14leR.jpg', '2026-09-25'),
    ('Whalefall', 106, 1255833, 'Following the death of his father, Jay Gardiner goes diving off the central Coast of California in search of his remains, but is swallowed by a massive sperm whale. While trapped inside its belly with only one hour of oxygen left, Jay comes to realize that the hard-earned lessons his father imparted may be the key to his escape.', '/vjTYUTgh9nO88i6HZ4YPRhiFL05.jpg', '2026-10-14'),
    ('I Play Rocky', 128, 1286656, 'The electrifying true story about an unknown actor with an unshakable belief that he wasn''t just meant to write Rocky—he was meant to be Rocky Balboa. Told "no" at every turn, Sylvester Stallone bets everything on himself, holding the line on playing the lead against seemingly impossible odds.', '/xE5tY3lppZUyG7WKKThsuYHuAHr.jpg', '2026-11-06'),
    ('Primetime', 110, 1375441, 'In 2006, To Catch a Predator host Chris Hansen sets out to make television history. When a high stakes operation goes fatally wrong, his veneered dream of fame curdles into a nightmare of performative justice.', '/lmrulvLbmaejTix1YaMxo1oGhH1.jpg', '2026-09-23'),
    ('Fjord', 146, 1401459, 'Following the deaths of Mihai''s parents, Mihai and Lisbet Gheorghiu leave their life behind in Romania and move with their children to a remote village in Norway, hoping to rebuild their lives near Lisbet''s family. There, they grow close to their neighbors, the Halbergs, whose warmth gives them hope for a fresh start. But the fragile peace begins to unravel when the Gheorghiu family’s young daughter, Elia, arrives at school covered in bruises.', '/3PPPIeSdeivjUn3O9RahGiaJ9b8.jpg', '2026-06-13'),
    ('Klara and the Sun', 116, 858035, 'When Klara, an Artificial Friend who wants nothing more than to find the perfect home, meets Josie, each immediately senses a kindred spirit in the other. Josie has a fraught relationship with her mother and they''ve suffered great loss, but Klara''s innocent wonder and unwavering loyalty begin to heal the family and bring light to Josie''s complicated world.', '/xqovj2p6HRsgHxN81qYAYF4StgM.jpg', '2026-10-21'),
    ('Ranabaali', 179, 1389379, 'Set in 19th-century British India, a fierce leader rises from a drought-stricken land to fight colonial oppression and atrocities.', '/cXaCyYYbafVyMrs8rwKmxezBYPJ.jpg', '2026-10-15'),
    ('Fatherland', 82, 1437696, 'In 1949, German writer Thomas Mann and his daughter Erika embark on a road trip across a Germany in ruins, from US-dominated Frankfurt to Soviet-controlled Weimar.', '/oNejN1l69nBF8LdQwy5FkAQZT44.jpg', '2026-06-19'),
    ('DNK', 136, 1641520, 'A young man with a compulsive stealing habit brings trouble upon his family, who must deal with the consequences of his actions.', '/ycduYExZfOc2baqjNT3pUf90sQu.jpg', '2026-11-12'),
    ('Focker-in-Law', 105, 1400336, 'Henry, son of Greg and Pam Focker, aims to marry Olivia, a strong-willed former hostage negotiator who appears to be his complete mismatch. To Greg''s shock, stepdad Jack Byrnes takes a liking to Olivia, and her unprecedented rise into his Circle of Trust sparks chaos in the family before Jack''s 80th birthday party.', '/iHJhSfqFpDMOyeMc6h6BOeHxse2.jpg', '2026-11-21'),
    ('Always Yours, Never Mine', 115, 1748404, 'Across thirty years, several almosts, and timing that is never quite right, two people keep crossing paths – always on the verge of being together, but never quite making it.', '/sDAbgrVhhdQxkPQwtBWpGhVtJ5b.jpg', '2026-09-30'),
    ('O.M: Operation Mole', 178, 1384528, 'Set across the temple corridors of Tirupati and Tiruvannamalai, an elite undercover operative infiltrates a sprawling transnational red sanders syndicate. As criminal politics escalate, a covert task force launches Operation Mole to dismantle the cartel from within.', '/vFnFLqXjf7RQfkNxrrys43BZKxJ.jpg', '2026-11-19'),
    ('Possible Love', 165, 1483525, 'A laid-off worker and his wife cross paths with a documentary filmmaker and her spouse and confront their hidden desires.', '/1ERGPNiKtnEcsvJS1ywsmqmcIDO.jpg', '2026-09-23'),
    ('Kung Fu Soccer', 106, 1491920, 'Dismissed as underdogs before they even step onto the pitch, the Emei Women''s Football Team enters the prestigious Supreme Invincible Cup determined to prove everyone wrong. Led by captain Shuangshuang, star striker Yulong, and mentor Xu Feng, the team combines martial arts mastery with football skill in a thrilling quest for victory. Against mounting challenges and impossible odds, they fight to make their mark and chase their championship dream.', '/kTf9kJ3QMQqYs6wNdYJeVtwIZ2Z.jpg', '2026-07-11'),
    ('Scene', 149, 1402181, 'Inbaraj, a police officer, is forced to come back from retirement when a new case resembles one he closed years ago. This time, he must solve it with a chaotic and troublesome team. As they struggle to work together and deal with the twists and turns of the case, the investigation takes them on a chaotic and unpredictable ride.', '/kfc4w3OX8QsFm8f9MPUdmGheNl3.jpg', '2026-11-05'),
    ('Monster Mia', 82, 1572116, '12-year-old Mia and her scruffy pet rat Quentin are sent to the mysterious Rotwood Academy after one too many problems at school. The new school gives her the creeps, and Mia needs to figure a way out before the students realize she isn''t a monster like them! But the vice principal Van Vlad hosts a particular dislike for humans, and Mia is scared he has seen through her act...', '/rlAFhlAdaUoujDxWRxBCVwM8esY.jpg', '2026-09-03'),
    ('Ali G: Who Iz I?', 89, 1727734, 'After twenty years spent "chillin'', tokin'' and bonin''", Ali G is shocked to discover that his long-term girlfriend, Julie, is 8 months pregnant. Faced with an extra mouth to feed, he gets off his batty and heads to America to reclaim his former glory… but soon encounters adversaries who will ultimately threaten his and his child''s very existence.', '/uTyVxPeWX8Ai30IQoyDDQONNcq.jpg', '2026-10-22'),
    ('Mookuthi Amman 2', 144, 1327835, 'A queen sacrifices herself to protect her son, the prince, from invading enemies.Mookuthi Amman returns to protect the child and confronts a mysterious woman who embodies a new and dangerous evil.', '/dNNzsstJeQxnESyH0hZcLGblLMz.jpg', '2026-11-06'),
    ('THE FURTHER MIS-ADVENTURES OF CLIFF BOOTH', 141, 1457866, 'Eight years after the events of Once Upon a Time in... Hollywood, Cliff Booth returns to a changing Los Angeles. Now working as a fixer in the shadows of the Hollywood studio system, Cliff finds himself entangled in a dangerous web of secrets, crimes and betrayals that will test everything he knows about loyalty and survival.', '/thX8Rs7nfgmPHfCgjoFuRovy49l.jpg', '2026-11-24'),
    ('Arrietty', 95, 51739, '14-year-old Arrietty and the rest of the Clock family live in peaceful anonymity as they make their own home from items "borrowed" from the house''s human inhabitants. However, life changes for the Clocks when a human boy discovers Arrietty.', '/3lSRaSjDp2nkXMQkzzjpRi3035O.jpg', '2010-07-16'),
    ('Josephine', 119, 1299329, 'After eight-year-old Josephine accidentally witnesses a brutal assault, she begins acting out violently to protect herself. This emotional trauma leads to conflicts between her parents as they search for justice and a way to feel safe again.', '/6pUSCeInGp4Ut3rqgPNWUrmKBUi.jpg', '2026-11-19'),
    ('NAZA', 77, 1755291, 'Filmed at night from Tel Aviv rooftops, this investigative documentary examines the civilian casualties of Israel''s military operations in Gaza and the systems behind targeted killings of Palestinians.', '/cbxiZ1l21KUATu2KKQQ8J8fJhpe.jpg', '2026-09-25'),
    ('The Restoration at Grayson Manor', 96, 1528009, 'The foundations of Grayson Manor are shaken when an accident leaves Boyd Grayson handless and his mother invests in radical new technology to help him.', '/m9aKkiCwlQWri27z9WEwezfkUcw.jpg', '2026-10-29'),
    ('Tom and Jerry: Forbidden Compass', 99, 1497970, 'During a chase inside a museum, Tom and Jerry find an ancient magical compass and end up being transported through time. Lost in a distant era, they will need to work together to find a way back home.', '/5qttWFjsO62k88civZaDMHiBTvy.jpg', '2025-08-02'),
    ('The Devils', 112, 31767, 'In 1634 France, charismatic Father Urbain Grandier becomes the target of sexually depraved Sister Jeanne''s accusations of witchcraft, which corrupt officials of church and state are all too happy to exploit.​​​​​​​​​​​​​​​​', '/y1k7eiOFc6fzm8XeTa1kNGx6JIs.jpg', '1971-07-16'),
    ('Nightborn', 92, 964849, 'In Finnish forest, Saga and her husband Jon embark on a new chapter as parents. But Saga''s joy is overshadowed by a chilling suspicion about their newborn, unbeknownst to Jon, causing a rift as she alone grapples with the disturbing truth.', '/cF1g9qtuRyATaZ75O6zRop2zmfZ.jpg', '2026-07-01'),
    ('Udta Teer', 137, 1375156, 'An amnesiac Pakistani spy wakes up believing he is a patriotic Indian counter-terrorism officer.', '/tvICKypVlW7Iio4KVs7NousbSKi.jpg', '2026-10-23'),
    ('Avedon', 104, 1666787, 'Richard Avedon''s photographs didn''t just reflect culture, they shaped it, and continue to do so. The feature documentary AVEDON traces the life and legacy of an artist who used fashion, portraiture, and commercial photography to explore identity, power, fear and beauty. With unprecedented access to Avedon''s archive, including never before seen photos, behind the scenes recordings, and interviews with those who knew him best, AVEDON is a visually stunning examination of the mind of an artist who shaped our collective image of the 20th century.', '/ziyEHM0P1TgvhVXIqqguoMAD0TJ.jpg', '2026-11-06'),
    ('Itllu Arjuna', 164, 1440539, 'A mute man with exceptional skills falls in love, proving that true feelings do not always need words.', '/i8WRWBdLhbAI6z3aaQAKuYf5g4T.jpg', '2026-11-12'),
    ('Bachelor Party D''eux', 132, 1533928, 'When urban chaos erupts around them, a band of honour-bound thieves must pull off a dangerous escape together, refusing to abandon each other despite deadly obstacles in their path.', '/2YVd84sp7iPcvQxXk0PfhDDC6GT.jpg', '2026-11-19'),
    ('ENE Repeat', 163, 1505644, 'Vivek and his gang of friends embark on an attempt to create an ambitious survival film.', '/qMBlRfQNusaUhhBAIcHmforVTW5.jpg', '2026-11-18'),
    ('Pehla Pyaar Doosri Baar', 150, 1772549, 'Three friends attend their school reunion and enter into different relationships, discovering the trials, tribulations, allure, and absurdities of love.', '/tGS4b47RIpF3DTAkezHBqfYNTm2.jpg', '2026-10-23'),
    ('Bouma', 113, 1733518, 'A struggling singer returns to an isolated, secret-shrouded estate tied to her own forgotten past. Simultaneously, a police investigation into a series of missing women intersects with the estate, blurring past memories and active crime.', '/l526Yk6NJeEhxSx9dmRMPOwt3tT.jpg', '2026-11-12'),
    ('Haiku', 143, 1593350, 'A charismatic young man uses poetry to navigate the complex maze of modern romance to protect his fragile relationship. Later, he must overcome deep generational divides to keep his love alive.', '/thZGedKvZnnvuLpNWEA1nmalM7K.jpg', '2026-10-23'),
    ('Nayyi Navelli', 138, 1654581, 'A new bride''s arrival turns a turbulent household in Meerut into a picture of domestic harmony, until her brother-in-law grows convinced that his seemingly perfect sister-in-law is secretly a witch.', '/aZEKuzGt7ObqoKjTM4kcMd0klYy.jpg', '2026-10-16'),
    ('Disco', 145, 1612811, 'An ordinary man undergoes a transformation as he enters the dark and dangerous world of the underworld.', '/yZ3AeO4bGYkSVT4onkAbLPTOSXe.jpg', '2026-11-06'),
    ('John Doe', 149, 1655020, 'A police officer investigates a young boy''s disappearance and uncovers a serial murder case involving 17 other missing children in a Tamil Nadu town.', '/nt7ErINVZAJ3PIprfSYJJshaFJc.jpg', '2026-11-13'),
    ('Aakasamlo Oka Tara', 159, 1322273, 'A girl from a remote village dreams of becoming an astronaut and wishes to defy the odds and doubts from those around her.', '/tN7NLrqxwhDsAgXuJSMg3CPmtTj.jpg', '2026-11-20'),
    ('Aadarsha Kutumbam House No: 47 - AK47', 149, 1496785, 'A tight-knit family faces an unexpected crisis that threatens their bond, forcing them to re-evaluate their values and fight to stay united.', '/1Z0ypXqSRWjnjPRVU6YiHwawsLC.jpg', '2026-10-30'),
    ('Gondhal', 120, 1576389, 'Suman, a newly-wedded wife in Maharashtra''s Gondhal rituals, conspires with Gondhali Saheba to kill her husband, Anand. They plan to carry out an escape that jeopardises her soul amid drum-driven ritual and divine omens, blurring the distinction between salvation and damnation in a citywide verdict of fire, blood, and awe.', '/hUIXIenoIPPhEUFcfR5PBSLX9oZ.jpg', '2025-11-14'),
    ('Pyre', 111, 1374689, 'In the Himalayan Mountain range, a rural village loses its inhabitants to the city’s allure while an elderly couple, Padam Singh and Tulsi, live in desolate isolation. Their days are filled with routine and occasional humour as they mask their loneliness. Their son’s absence gnaws at them, and when a letter arrives promising his return, it reignites their hearts with joy and anticipation. However, the reunion does not unfold as expected, shattering their hopes. As the film climaxes, the spectator is confronted with a more rueful plight, deeply engaging the audience’s empathy.', '/vnA3CaEYrXIHyxmyv8oegshSSgE.jpg', '2026-10-30'),
    ('Prahaar: The Untold Story of Ujjwal Nikam', 141, 1081010, 'Public prosecutor Ujjwal Nikam takes on one of the most high-profile criminal cases in India’s history, leading the prosecution in the trial of Ajmal Kasab following the 26/11 Mumbai terror attacks. As he battles to uncover the truth and secure justice, Nikam must confront the immense personal and professional burden of a case that will define his legacy.', '/wTrBTNfHHmpPwiB9rpn0tGbSW1m.jpg', '2026-10-16'),
    ('Crazy Kalyanam', 144, 1610188, 'The story focuses on a village girl, played by Anupama Parameswaran, who faces struggles regarding her inability to get married, which drives the comedic and family-oriented plot.', '/dt6VT9GSCH6PSnTvngbF0IEnAho.jpg', '2026-10-16'),
    ('#Cult', 152, 1637705, 'A group of young boys head to a party expecting a night of fun, but soon discover the reality is far darker than they imagined. What starts as excitement spirals into terror, pushing them into a brutal fight for survival.', '/lU5R4437Dtgom9q5HVlt6ArxwcM.jpg', '2026-10-30'),
    ('Appa Kutty', 134, 1680033, NULL, '/6h0XuDkjNOTYpmdMop5nDrBREum.jpg', '2026-11-20'),
    ('Sathyavan Savithiri', 136, 1540824, 'Follows a cheerful lawyer whose life turns upside down when she takes up a major case while navigating her own emotional pain and fighting for social justice.', '/6CTZmOW9YrHxxaYjK56rB8DvefR.jpg', '2026-11-20'),
    ('Bohurupi: The Golden Daku', 168, 1607833, 'A cop tries to track down Bikram Pramanik, a master of disguise whose wife is a pickpocket.', '/z3lDOhg4C965ri8bPVPnyTIaww9.jpg', '2026-10-15'),
    ('Tu Hai Meri Kiran', 140, 1785611, 'What starts as a real connection for her turns into his all-consuming obsession. As love darkens, the boundary between devotion and danger fades.', '/jjlqHKzDTPJXDl0eb77Q20Aipuc.jpg', '2026-10-23'),
    ('Enemy Of The Smuggler', 130, 1800255, 'Inspired by real customs investigations, a relentless battle unfolds against organized smuggling networks, exposing the hidden world of coastal operations, airport cartels and the officers determined to stop them.', '/pDZxgWM1t2fTOB5IUyPJGlDFthl.jpg', '2026-10-30')
